000255500_De_held_van_weleer_0_0.jpg","checkedAt":"2026-10-31","sha256":"5c82733681bc7b259ddd2be5e7a2134c16235aba41cf7bcc4571778644b4227d","bytes":120446,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100065,"language":"nl","bound_author_id":8800016,"text":"Een onrustige wereld stelt Vin en Elend voor nieuwe vragen over de macht die zij hebben bevochten. Terwijl asregens en aardbevingen het bestaan bedreigen, zoeken zij naar kennis die hun voorgangers hebben achtergelaten. Vin draagt de gevolgen van haar eerdere keuzes met zich mee. Elend probeert te begrijpen hoe hij anderen kan beschermen tegen een gevaar dat steeds moeilijker te doorgronden wordt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/141156/de-held-van-weleer.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022580301","key":{"isbn_13":"9789022580301"},"before":null,"after":{"work_id":975100066,"title":"Rijk van stormen","isbn_13":"9789022580301","isbn_10":"902258030X","language":"nld","publisher":"Meulenhoff Boekerij B.V.","id":975200137}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022580301","key":{"edition_id":"@edition:9789022580301"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/1835782/rijk-van-stormen.html","checkedAt":"2026-10-31","fact":"Retained reviewed prior identity/edition/content evidence"},{"url":"https://openlibrary.org/books/OL26319926M","checkedAt":"2026-10-31","fact":"Retained reviewed prior identity/edition/content evidence"},{"url":"https://metadata.isbn.nl/ie_fcache/0000522982_Rijk_van_stormen_0_0.jpg","checkedAt":"2026-10-31","sha256":"292cce9470eb057d355de7f7a45d712edd1ad78379e602a7cb832d8ae7de8578","bytes":318127,"fact":"Manual title/author/exact edition cover binding, readable pub