fcache/0000523519_Toren_van_de_dageraad_0_0.jpg","checkedAt":"2026-10-31","sha256":"0969f6d922c583a7f6d2d23597a2f759aa3f44953e332e23cdb03a582a7f9019","bytes":337928,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100067,"language":"nl","bound_author_id":924300125,"text":"Na ingrijpende verwondingen zoekt Chaol Westfall hulp bij de genezers van de Torre Cesme in Antica. Zijn reis naar het zuidelijke rijk heeft ook een politiek doel: steun vinden voor een dreigende oorlog. Terwijl herstel hem dwingt anders naar zichzelf te kijken, ontdekt hij dat de problemen rond hem groter zijn dan zijn eigen toekomst. Dit deel volgt een andere verhaallijn dan Aelins gelijktijdige strijd.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1835783/toren-van-de-dageraad.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789024580477","key":{"isbn_13":"9789024580477"},"before":null,"after":{"work_id":975100068,"title":"De Stenen Hemel","isbn_13":"9789024580477","isbn_10":"9024580471","language":"nld","publisher":"Luitingh-Sijthoff B.V., Uitgeverij","id":975200139}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024580477","key":{"edition_id":"@edition:9789024580477"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/1198623/de-gebroken-aarde-3-de-stenen-hemel.html","checkedAt":"2026-10-31","fact":"Retained reviewed prior identity/edition/content evidence"},{"url":"https://openlibrary.org/books/OL26461538M","checkedAt":"2026-10-31","fact":"Retained reviewed prior identity/edition/content evidence"},{"url":"https://metadata.isbn.nl/ie_fcache/0000527125_De_Stenen_Hemel_0_0.jpg","checkedAt":"2026-10-31","sha256":"5957f14d2a31a676d12c22ef99c965722690f3bdab44a1e9191eba24b7089893","bytes":577324,"fact":"Manual ti